/* Two existing supervisors, independent views and drafts; no connection reconfiguration. */
(() => {
  'use strict';
  const HQ='01a13305-2586-7e53-956b-d1f6b9aeab93',HAND='01a0c670-7a18-7243-a9af-9ae8cb0a2548';
  const handAssets=Object.freeze({"working":{"gif":"/api/work/attachment?id=321346cdbb9e4d3ba62a352f65d21164","still":"data:image/png;base64,"},"idle":{"gif":"/api/work/attachment?id=491cca9c46dc47e897b2b932001f3a2f","still":"data:image/png;base64,"},"completed":{"gif":"/api/work/attachment?id=b136fd25964449f9be8a577b4e262863","still":"data:image/png;base64,"}});
  const $=id=>document.getElementById(id),api=window.officeProjectThreadViews;
  if(!api||!$('workAssistantTitle')||$('workSupervisorTabs'))return;
  const root=$('workAssistantTitle').closest('.work-assistant'),content=root.querySelector('.work-conversation-content'),originalCompanion=$('workCompanion');
  if(!content||!originalCompanion)return;
  const make=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;};
  const storageKey='office-supervisor-observed-v1',key=r=>(r.host||'local')+'|'+r.id;
  let saved={};try{saved=JSON.parse(localStorage.getItem(storageKey)||'{}')||{};}catch(_){}
  const rows=[{id:HQ,host:'local',title:'Aemeath',project:'AI OFFICE',subtitle:'운영본부'},{id:HAND,host:'local',title:'The Hand',project:'고도·메두사',subtitle:'고도·메두사 총괄'}];
  const records=new Map(rows.map(row=>[row.id,{row,observed:saved[key(row)]?.observed||null,unread:saved[key(row)]?.unread||null,primed:false,data:null,intent:false,scroll:null,followBottom:true,error:'',history:null,historyLoading:false}]));
  let active=HQ;
  const style=make('link');style.rel='stylesheet';style.href='/supervisor-switch.css';document.head.append(style);
  const tabs=make('span','work-supervisor-tabs');tabs.id='workSupervisorTabs';tabs.dataset.independentWork='true';tabs.setAttribute('role','group');tabs.setAttribute('aria-label','대화할 총괄 선택');
  $('workAssistantTitle').replaceChildren(tabs);
  for(const r of records.values()){
    const button=make('button','work-supervisor-tab');button.type='button';button.dataset.threadId=r.row.id;
    const name=make('span','',r.row.title),state=make('small','work-supervisor-tab-state','연결 확인 중'),complete=make('span','work-supervisor-complete','완료');complete.hidden=true;
    button.append(name,state,complete);button.onclick=event=>select(r.row.id,event.isTrusted);tabs.append(button);Object.assign(r,{button,state,complete});
  }
  const originalNodes=[...content.children],aemeathView=make('div','work-supervisor-aemeath');aemeathView.id='workSupervisorAemeath';
  for(const child of originalNodes)aemeathView.append(child);content.append(aemeathView);
  const handView=make('div','work-supervisor-hand');handView.id='workSupervisorHand';handView.dataset.independentWork='true';handView.hidden=true;content.append(handView);
  const recipient=make('p','work-supervisor-recipient','보내는 대상: Aemeath · 운영본부');recipient.id='workSupervisorRecipient';$('workCommandForm').prepend(recipient);
  $('workCommand').setAttribute('aria-label','Aemeath 운영본부에 보낼 메시지');$('workCommand').placeholder='Aemeath에게 맡길 일';
  // Hidden composers cannot submit through an old pending Enter or programmatic submit.
  $('workCommandForm').addEventListener('submit',event=>{if(active!==HQ){event.preventDefault();event.stopImmediatePropagation();}},true);
  const retry=$('workRetry'),retryHidden=()=>{if(retry)retry.classList.toggle('is-supervisor-away',active!==HQ);};
  const handCompanion=make('aside','work-companion work-hand-companion');handCompanion.id='workHandCompanion';handCompanion.hidden=false;handCompanion.setAttribute('aria-label','The Hand 상태');
  const stage=make('div','work-companion-stage'),animation=make('img','work-companion-animation'),still=make('img','work-companion-still');animation.id='workHandCompanionAnimation';still.id='workHandCompanionStill';animation.alt=still.alt='';stage.append(animation,still);
  const caption=make('div','work-companion-caption'),handStatus=make('p','work-hand-status','연결 확인 중');handStatus.id='workHandCompanionStatus';handStatus.setAttribute('role','status');handStatus.setAttribute('aria-live','polite');caption.append(make('strong','','The Hand'),handStatus);handCompanion.append(stage,caption);originalCompanion.after(handCompanion);
  const companionRail=originalCompanion.parentElement;companionRail.classList.add('work-supervisor-stack');companionRail.setAttribute('aria-label','Aemeath와 The Hand 상태');
  // A native button makes the whole monitor keyboard-accessible without nesting the alert controls.
  for(const [id,companion] of [[HQ,originalCompanion],[HAND,handCompanion]]){
    const monitor=make('button','work-supervisor-monitor-select');monitor.type='button';monitor.dataset.independentWork='true';monitor.dataset.threadId=id;
    monitor.setAttribute('aria-controls',id===HQ?aemeathView.id:handView.id);
    monitor.onclick=event=>select(id,event.isTrusted);companion.append(monitor);records.get(id).monitor=monitor;
  }
  // Move the original widget nodes so calendar selection/weather timers keep their listeners and state.
  const masthead=$('workMasthead'),calendar=$('workCalendar'),ambient=$('workAmbient');
  if(masthead&&calendar&&ambient){
    const tools=make('div','work-masthead-tools');tools.dataset.independentWork='true';
    const calendarMenu=make('details','work-top-calendar');calendarMenu.id='workTopCalendar';
    const trigger=make('summary'),dateLabel=make('span','work-top-calendar-date');
    trigger.append(make('span','work-top-calendar-mark','▦'),dateLabel,make('span','work-top-calendar-caret','▾'));trigger.setAttribute('aria-label','상단 캘린더 펼치기');
    function updateCalendarLabel(date){const chosen=date||calendar.querySelector('[data-calendar-day][aria-pressed=true]')?.dataset.calendarDay;if(chosen)dateLabel.textContent=new Date(chosen+'T12:00:00').toLocaleDateString('ko-KR',{month:'long',day:'numeric',weekday:'short'});else if(!dateLabel.textContent)dateLabel.textContent='캘린더';}
    calendarMenu.append(trigger,calendar);tools.append(calendarMenu,ambient);masthead.append(tools);masthead.classList.add('has-top-widgets');updateCalendarLabel();
    const grid=$('workCalendarGrid');if(grid)new MutationObserver(()=>updateCalendarLabel()).observe(grid,{childList:true});
    calendar.addEventListener('click',event=>{const day=event.target.closest('[data-calendar-day]');if(day){updateCalendarLabel(day.dataset.calendarDay);calendarMenu.open=false;}});
    calendarMenu.addEventListener('keydown',event=>{if(event.key==='Escape')calendarMenu.open=false;});
    document.addEventListener('pointerdown',event=>{if(calendarMenu.open&&!calendarMenu.contains(event.target))calendarMenu.open=false;});
  }
  let hand;
  function persist(){try{localStorage.setItem(storageKey,JSON.stringify(Object.fromEntries([...records.values()].map(r=>[key(r.row),{observed:r.observed,unread:r.unread}]))));}catch(_) {}}
  function stateLabel(r){if(r.error||!r.data)return r.error?'조회 실패':'연결 확인 중';if(Date.now()-(r.checkedAt||0)>45000)return '갱신 지연';const status=r.data.status||'';return status==='진행 중'?'작업 중':status.includes('승인')?'승인 대기':status.includes('입력')?'입력 대기':status==='확인 필요'?'확인 필요':'대기 중';}
  function render(){
    for(const r of records.values()){
      if(r.unread&&api.seen(r.row)===r.unread){r.unread=null;persist();}
      const selected=r.row.id===active,label=stateLabel(r),busy=label==='작업 중';r.button.setAttribute('aria-pressed',String(selected));r.button.classList.toggle('is-running',busy);r.button.classList.toggle('has-completion',!!r.unread);r.complete.hidden=!r.unread;r.state.textContent=label;
      r.frameState=busy?'working':['승인 대기','입력 대기','확인 필요'].includes(label)?'attention':r.unread?'completed':r.error||!r.data||label==='갱신 지연'?'unknown':'idle';
      (r.row.id===HQ?originalCompanion:handCompanion).dataset.frameState=r.frameState;
      r.button.setAttribute('aria-label',r.row.title+' · '+label+(r.unread?' · 새 완료 결과 있음':'')+' · '+(selected?'현재 대화':'전환'));
      r.monitor.setAttribute('aria-pressed',String(selected));r.monitor.setAttribute('aria-label',r.row.title+' 채팅으로 전환 · '+label+(selected?' · 현재 대화':''));r.monitor.title=r.row.title+' 채팅으로 전환';
    }
    const r=records.get(HAND),label=stateLabel(r),kind=label==='작업 중'?'working':r.unread?'completed':'idle';
    handCompanion.dataset.state=kind;handStatus.textContent=r.unread&&label!=='작업 중'?'새 완료 결과를 확인해 주세요':label;
    const art=handAssets[kind];if(art){if(animation.getAttribute('src')!==art.gif)animation.src=art.gif;if(still.getAttribute('src')!==art.still)still.src=art.still;}
    originalCompanion.dataset.supervisorSelected=String(active===HQ);handCompanion.dataset.supervisorSelected=String(active===HAND);
    root.dataset.supervisor=active===HQ?'aemeath':'hand';root.dataset.frameState=records.get(active).frameState;retryHidden();
  }
  function observe(data){
    const r=records.get(data.id);if(!r)return;r.error='';r.data=data;r.checkedAt=Date.now();
    if(data.completion){
      if(r.observed&&r.observed!==data.completion){r.unread=data.completion;r.intent=false;if(r.row.id===HQ)r.history=null;}
      // The first existing final is a baseline, not a newly completed task.
      r.observed=data.completion;
    }
    r.primed=true;persist();render();
  }
  async function loadMainConversation(r){
    if(r.historyLoading)return;
    r.historyLoading=true;
    try{
      const data=await api.readHistory(r.row);
      window.officeMainNativeConversation?.update(data);
      r.history={completion:data.completion};
      if(!r.historyBackfilled){
        let cursor=data.cursor;
        for(let count=0;cursor&&count<3;count++){
          const response=await fetch('/api/work/project-panel?'+new URLSearchParams({id:HQ,host:'local',cursor}),{cache:'no-store'});
          if(!response.ok)break;
          const older=await response.json();if(older.error)break;
          window.officeMainNativeConversation?.update(older);cursor=older.cursor;
        }
        r.historyBackfilled=true;
      }
      requestAnimationFrame(confirmMainConversation);
    }catch(error){r.error=error.message;render();}
    finally{r.historyLoading=false;}
  }
  function confirmMainConversation(){
    const r=records.get(HQ),log=$('workMessages');
    if(active!==HQ||!r.intent||!r.unread||!log)return;
    const messages=window.officeMainNativeConversation?.messages()||[];
    if(api.confirm(r.row,log,messages,r.unread,true)){r.unread=null;persist();render();}
  }
  function select(id,intent=false){
    const next=records.get(id);if(!next)return;const previous=records.get(active);
    if(active===HQ){const view=window.officeMainChatScrollState?.();previous.scroll=view?.top??$('workMessages').scrollTop;previous.followBottom=view?.following??($('workMessages').scrollHeight-$('workMessages').clientHeight-$('workMessages').scrollTop<=40);}else if(hand){previous.scroll=hand.log.scrollTop;previous.followBottom=hand.log.scrollHeight-hand.log.clientHeight-hand.log.scrollTop<=40;}
    active=id;window.officeMainChatVisible=active===HQ;aemeathView.hidden=active!==HQ;handView.hidden=active!==HAND;originalCompanion.hidden=false;handCompanion.hidden=false;
    hand?.setVisible(active===HAND,intent,next.followBottom||next.scroll===null?null:next.scroll);next.intent=intent;
    if(active===HQ){window.officeMainChatScrollTo?.(next.followBottom||next.scroll===null?null:next.scroll);requestAnimationFrame(()=>{if(!window.officeMainChatScrollTo)$('workMessages').scrollTop=next.followBottom||next.scroll===null?$('workMessages').scrollHeight:next.scroll;loadMainConversation(next);requestAnimationFrame(confirmMainConversation);});}
    render();
  }
  window.officeSupervisorSelect=id=>select(id,false);
  addEventListener('office-project-thread-state',event=>observe(event.detail));
  addEventListener('office-project-completion-seen',event=>{const r=records.get(event.detail.id);if(r?.unread===event.detail.completion){r.unread=null;persist();render();}});
  addEventListener('office-department-sprites-ready',render);
  const mainLog=$('workMessages');
  for(const type of ['pointerdown','wheel','keydown'])mainLog.addEventListener(type,event=>{if(!event.isTrusted)return;records.get(HQ).intent=true;requestAnimationFrame(confirmMainConversation);});
  mainLog.addEventListener('scroll',()=>requestAnimationFrame(confirmMainConversation));
  addEventListener('office-main-conversation-rendered',()=>requestAnimationFrame(confirmMainConversation));
  hand=api.mount({...records.get(HAND).row,kind:'codex'},handView);
  records.get(HAND).scroll=hand.scroll;records.get(HAND).followBottom=hand.scroll===null;
  const handForm=hand.element.querySelector('form');handForm.prepend(make('p','work-supervisor-recipient','보내는 대상: The Hand · 고도·메두사 총괄'));hand.input.placeholder='The Hand에게 맡길 일';hand.input.setAttribute('aria-label','The Hand 고도·메두사 총괄에 보낼 메시지');
  handForm.addEventListener('submit',event=>{if(active!==HAND){event.preventDefault();event.stopImmediatePropagation();}},true);
  const handLabels=hand.element.querySelector('.project-window-meta');if(handLabels)handLabels.setAttribute('aria-label','The Hand 실제 대화 연결 상태');
  let polling=false;
  let backgroundStateAt=0;
  async function poll(){if(polling||document.hidden)return;polling=true;try{if(active===HQ)await loadMainConversation(records.get(HQ));else if(Date.now()-backgroundStateAt>12000){await api.readState(records.get(HQ).row);backgroundStateAt=Date.now();}}catch(error){records.get(HQ).error=error.message;render();}finally{polling=false;}}
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});
  select(HQ,false);poll();setInterval(poll,3000);
  window.officeSupervisorView={current:()=>active,targets:()=>rows.map(r=>({id:r.id,title:r.title})),select:id=>select(id,false)};
})();
